from pathlib import Path
p=Path('/home/ubuntu/labrkp-workforce/client/src/pages/WorkerConsole.tsx')
s=p.read_text()
s=s.replace('''  const [pendingRequest, setPendingRequest] = useState<any>(null);\n  const [requestStatus, setRequestStatus] = useState("Pending");''','''  const [requests, setRequests] = useState<any[]>([]);\n  const [pendingRequest, setPendingRequest] = useState<any>(null);\n  const [requestStatus, setRequestStatus] = useState("Pending");''',1)
old='''  useEffect(() => { if (authLoading || !user) return; let active = true; setRequestLoading(true); fetch("/api/workers/my-applications").then((response) => response.ok ? response.json() : []).then((applications) => { const approved = applications.find((item: any) => item.status === "Approved"); if (!approved) { setAccessDenied(true); return null; } setWorkerId(approved.applicationId); return fetch(`/api/workers/${encodeURIComponent(approved.applicationId)}/bookings`).then((response) => { if (response.status === 401) { setAccessDenied(true); return []; } return response.ok ? response.json() : []; }); }).then((rows) => { if (!active || !rows) return; const booking = rows.find((item: any) => ["Pending", "Accepted", "OnTheWay"].includes(item.status)); if (booking) { setPendingRequest(booking); setRequestStatus(booking.status); } }).catch(() => setAccessDenied(true)).finally(() => { if (active) setRequestLoading(false); }); return () => { active = false; }; }, [authLoading, user]);'''
new='''  const loadRequests = async () => { setRequestLoading(true); try { const applicationsResponse = await fetch("/api/workers/my-applications"); const applications = applicationsResponse.ok ? await applicationsResponse.json() : []; const approved = applications.find((item: any) => item.status === "Approved"); if (!approved) { setAccessDenied(true); return; } setWorkerId(approved.applicationId); const response = await fetch(`/api/workers/${encodeURIComponent(approved.applicationId)}/bookings`); if (response.status === 401) { setAccessDenied(true); return; } const rows = response.ok ? await response.json() : []; setRequests(rows); const active = rows.find((item: any) => ["Accepted", "OnTheWay"].includes(item.status)); if (active) { setPendingRequest(active); setRequestStatus(active.status); } } catch { setAccessDenied(true); } finally { setRequestLoading(false); } };
  useEffect(() => { if (authLoading || !user) return; void loadRequests(); }, [authLoading, user]);'''
if old not in s: raise SystemExit('load effect missing')
s=s.replace(old,new,1)
old2='''  const declineRequest = async () => { if (!pendingRequest?._id) return; const response = await fetch(`/api/bookings/${pendingRequest._id}/decline`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ workerId }) }); if (response.ok) { const updated = await response.json(); setPendingRequest(updated); setRequestStatus(updated.status); localStorage.setItem("labrkp_pending_booking", JSON.stringify(updated)); } };\n  const acceptRequest = async () => { if (!pendingRequest?._id) return; const response = await fetch(`/api/bookings/${pendingRequest._id}/accept`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ workerId }) }); if (response.ok) { const updated = await response.json(); setPendingRequest(updated); setRequestStatus(updated.status); localStorage.setItem("labrkp_pending_booking", JSON.stringify(updated)); } };'''
new2='''  const updateRequest = (updated: any) => { setRequests((current) => current.map((item) => item._id === updated._id ? updated : item)); if (pendingRequest?._id === updated._id) { setPendingRequest(updated); setRequestStatus(updated.status); } localStorage.setItem("labrkp_pending_booking", JSON.stringify(updated)); };
  const declineRequest = async (booking = pendingRequest) => { if (!booking?._id) return; const response = await fetch(`/api/bookings/${booking._id}/decline`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ workerId }) }); if (response.ok) updateRequest(await response.json()); };
  const acceptRequest = async (booking = pendingRequest) => { if (!booking?._id) return; const response = await fetch(`/api/bookings/${booking._id}/accept`, { method: "POST", headers: { "Content-Type": "application/json" }, body: JSON.stringify({ workerId }) }); if (response.ok) updateRequest(await response.json()); };'''
if old2 not in s: raise SystemExit('actions missing')
s=s.replace(old2,new2,1)
start=s.index('{requestLoading && <section')
end=s.index('<div className="mt-8 grid gap-5', start)
new_ui='''{requestLoading && <section className="mt-8 rounded-[26px] border border-[#e4ebe0] bg-white p-6 text-sm text-[#819087]">Checking your booking requests…</section>}{!requestLoading && requests.filter((item) => item.status === "Pending").length === 0 && <section className="mt-8 rounded-[26px] border border-[#e4ebe0] bg-white p-8 text-center"><Clock3 className="mx-auto text-[#789b4e]" size={28} /><h3 className="mt-3 font-display text-xl font-semibold text-[#203a34]">No pending booking requests</h3><p className="mt-1 text-sm text-[#819087]">New customer requests will appear here automatically.</p><button onClick={() => void loadRequests()} className="mt-4 rounded-full bg-[#203a34] px-4 py-2 text-xs font-bold text-white">Refresh requests</button></section>}{requests.filter((item) => item.status === "Pending").length > 0 && <section className="mt-8"><div className="flex items-end justify-between"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-[#789159]">Action needed</p><h3 className="mt-1 font-display text-2xl font-semibold text-[#203a34]">Pending booking requests</h3></div><span className="rounded-full bg-[#fff0c5] px-3 py-1.5 text-xs font-bold text-[#96722d]">{requests.filter((item) => item.status === "Pending").length} waiting</span></div><div className="mt-4 grid gap-4 lg:grid-cols-2">{requests.filter((item) => item.status === "Pending").map((booking) => <article key={booking._id} className="rounded-[26px] border-2 border-[#d7e9ad] bg-[#f5fbe9] p-5"><div className="flex items-start justify-between gap-3"><div><p className="text-xs font-bold uppercase tracking-[0.15em] text-[#789159]">New request</p><h4 className="mt-1 font-display text-xl font-semibold text-[#203a34]">{booking.service}</h4></div><span className="rounded-full bg-[#fff0c5] px-2.5 py-1 text-[10px] font-bold text-[#96722d]">Pending</span></div><div className="mt-4 space-y-2 text-sm text-[#687a6e]"><p><strong>Customer:</strong> {booking.customer?.fullName}</p><p><strong>When:</strong> {booking.date} at {booking.time}</p><p><strong>Location:</strong> {booking.location}</p><p><strong>Fee:</strong> Rs. {Number(booking.price || 0).toLocaleString()} · <strong>You earn:</strong> Rs. {Number(booking.workerEarning || 0).toLocaleString()}</p></div><div className="mt-5 flex gap-2"><button onClick={() => void acceptRequest(booking)} className="flex-1 rounded-full bg-[#203a34] px-4 py-2.5 text-sm font-bold text-white">Accept request</button><button onClick={() => void declineRequest(booking)} className="rounded-full border border-[#efc9bf] bg-white px-4 py-2.5 text-sm font-bold text-[#a45843]">Reject</button></div></article>)}</div></section>}{pendingRequest && ["Accepted", "OnTheWay"].includes(requestStatus) && <section className="mt-6 rounded-[26px] border-2 border-[#cde8ba] bg-[#eff9e8] p-5"><div className="flex flex-col justify-between gap-4 sm:flex-row sm:items-center"><div><p className="text-xs font-bold uppercase tracking-[0.16em] text-[#587060]">Active booking</p><h3 className="mt-1 font-display text-xl font-semibold text-[#203a34]">{pendingRequest.service} · {pendingRequest.customer?.fullName}</h3><p className="mt-2 text-sm text-[#687a6e]">{pendingRequest.date} at {pendingRequest.time} · {pendingRequest.location}</p></div><button onClick={startLocationSharing} className="rounded-full bg-[#203a34] px-4 py-2.5 text-sm font-bold text-white">Share live GPS</button></div><div className="mt-4 flex flex-wrap gap-3 text-xs font-semibold text-[#5f7664]"><span className="rounded-full bg-white px-3 py-2">Accepted · ETA 20 min</span><span className="rounded-full bg-white px-3 py-2">Fee Rs. {Number(pendingRequest.price || 0).toLocaleString()}</span><span className="rounded-full bg-white px-3 py-2">{locationStatus}</span></div></section>}'''
s=s[:start]+new_ui+s[end:]
p.write_text(s)
